<script setup>
import {reactive,ref,computed,useId} from 'vue';import {ArrowUp,ArrowDown} from '@lucide/vue';import {dispatch} from '../state';import {t,errorText} from '../i18n';import {templateEditPreview} from '../../core/checklist-templates.mjs';import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';
const props=defineProps({template:Object}),emit=defineEmits(['close','saved']),editing=Boolean(props.template?.id&&!props.template.builtin),id=editing?props.template.id:crypto.randomUUID(),operation=crypto.randomUUID(),formId=useId();let sequence=0;const row=(task={})=>({key:++sequence,title:task.title??'',stage:task.stage??'preparation',notes:task.notes??''});const draft=reactive({name:props.template?.name??'',tasks:(props.template?.tasks??[{}]).map(row)}),review=ref(false),busy=ref(false),error=ref('');const definition=()=>({name:draft.name,tasks:draft.tasks.map(({title,stage,notes})=>({title,stage,notes}))});const preview=computed(()=>{try{return templateEditPreview(editing?props.template:null,definition())}catch{return null}});
function move(index,delta){const target=index+delta;if(target<0||target>=draft.tasks.length)return;const [task]=draft.tasks.splice(index,1);draft.tasks.splice(target,0,task)}
function inspect(){error.value='';try{templateEditPreview(editing?props.template:null,definition());review.value=true}catch(caught){error.value=errorText(caught)}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await dispatch(editing?'template.update':'template.create',{id,...definition()},operation);emit('saved',id)}catch(caught){error.value=errorText(caught)}finally{busy.value=false}}
</script>
<template><AppDialog :title="t(editing?'editChecklistTemplate':'newChecklistTemplate')" wide :busy="busy" @close="emit('close')"><p class="notice">{{t('templateIndependentHelp')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><form v-if="!review" :id="formId" @submit.prevent="inspect"><FormField :label="t('name')" required v-slot="{id}"><input :id="id" v-model="draft.name" required maxlength="150"/></FormField><section v-for="(task,index) in draft.tasks" :key="task.key" class="panel"><div class="panel-heading"><h3>{{t('templateTaskNumber',{number:index+1})}}</h3><div class="toolbar"><button type="button" class="button small" :disabled="index===0" :aria-label="t('templateMoveUp',{number:index+1})" @click="move(index,-1)"><ArrowUp :size="14"/></button><button type="button" class="button small" :disabled="index===draft.tasks.length-1" :aria-label="t('templateMoveDown',{number:index+1})" @click="move(index,1)"><ArrowDown :size="14"/></button><button type="button" class="button small danger" :disabled="draft.tasks.length===1" :aria-label="t('templateRemoveTask',{number:index+1})" @click="draft.tasks.splice(index,1)">{{t('remove')}}</button></div></div><div class="panel-body form-grid"><FormField :label="t('task')" required v-slot="{id}"><input :id="id" v-model="task.title" required maxlength="500"/></FormField><FormField :label="t('type')" required v-slot="{id}"><select :id="id" v-model="task.stage"><option v-for="stage in ['preparation','work','finishing','custom']" :key="stage" :value="stage">{{t(stage)}}</option></select></FormField><FormField :label="t('notes')" wide v-slot="{id}"><textarea :id="id" v-model="task.notes" maxlength="10000"/></FormField></div></section><button type="button" class="button" :disabled="draft.tasks.length>=100" @click="draft.tasks.push(row())">{{t('addTask')}}</button></form><template v-else-if="preview"><h3>{{t('preview')}}</h3><p>{{props.template?.name||t('none')}} → <strong>{{preview.after.name}}</strong></p><p>{{t('templateDefinitionCounts',{before:editing?props.template.tasks.length:0,after:preview.after.tasks.length})}}</p><div class="table-wrap"><table><thead><tr><th>{{t('before')}}</th><th>{{t('after')}}</th></tr></thead><tbody><tr v-for="change in preview.changes" :key="change.index"><td><template v-if="change.before"><strong>{{change.before.title}}</strong><p>{{t(change.before.stage)}}</p><p v-if="change.before.notes">{{change.before.notes}}</p></template><span v-else>{{t('none')}}</span></td><td><template v-if="change.after"><strong>{{change.after.title}}</strong><p>{{t(change.after.stage)}}</p><p v-if="change.after.notes">{{change.after.notes}}</p></template><span v-else>{{t('none')}}</span></td></tr></tbody></table></div></template><template #footer><button class="button" :disabled="busy" @click="review?review=false:emit('close')">{{t(review?'back':'cancel')}}</button><button v-if="!review" class="button primary" type="submit" :form="formId">{{t('reviewTemplateChanges')}}</button><button v-else class="button primary" :disabled="busy||!preview" @click="save">{{t(busy?'saving':'save')}}</button></template></AppDialog></template>
